from taf.cloud.cbam.schemas.schema_base import CbamSchema


class VnfLcmOpOccLinks(CbamSchema):
    def __init__(self, self_link=None, list_link=None, cancel=None, fail=None,
                 vnf_instance=None, grant=None):
        self.self_link = self_link
        self.list_link = list_link
        self.cancel = cancel
        self.fail = fail
        self.vnf_instance = vnf_instance
        self.grant = grant

    @classmethod
    def from_response_dict(cls, resp_dict):
        def get_href_attribute(response, key):
            return response[key]['href'] if key in response else None
        self_link = resp_dict['self']['href']
        list_link = get_href_attribute(resp_dict, 'list')
        cancel = get_href_attribute(resp_dict, 'cancel')
        fail = get_href_attribute(resp_dict, 'fail')
        vnf_instance = get_href_attribute(resp_dict, 'vnfInstance')
        grant = get_href_attribute(resp_dict, 'grant')
        return cls(self_link=self_link,
                   list_link=list_link,
                   cancel=cancel, fail=fail,
                   vnf_instance=vnf_instance,
                   grant=grant)

    def as_dict(self):
        attributes = {'list': self.list_link,
                      'cancel': self.cancel,
                      'fail': self.fail,
                      'vnfInstance': self.vnf_instance,
                      'grant': self.grant}

        result = {k: {'href': v} for k, v in attributes.items() if v}
        result['self'] = {'href': self.self_link}

        return result


class VnfLcmOpOcc(CbamSchema):
    def __init__(self, operation_id=None, operation_state=None, state_entered_time=None, start_time=None,
                 vnf_instance_id=None, operation_type=None, is_automatic_invocation=None, operation_params=None,
                 is_cancel_pending=None, links=None, grant_id=None, operation_name=None, cancel_mode=None,
                 error=None, resource_changes=None, changed_info=None, additional_data=None):
        self.operation_id = operation_id
        self.operation_state = operation_state
        self.state_entered_time = state_entered_time
        self.start_time = start_time
        self.vnf_instance_id = vnf_instance_id
        self.operation_type = operation_type
        self.is_automatic_invocation = is_automatic_invocation
        self.operation_params = operation_params
        self.is_cancel_pending = is_cancel_pending
        self.links = links
        self.grant_id = grant_id
        self.operation_name = operation_name
        self.cancel_mode = cancel_mode
        self.error = error
        self.resource_changes = resource_changes
        self.changed_info = changed_info
        self.additional_data = additional_data

    @classmethod
    def from_response_dict(cls, resp_dict):
        links = None
        if '_links' in resp_dict:
            links = VnfLcmOpOccLinks.from_response_dict(resp_dict['_links'])

        return cls(operation_id=resp_dict['id'],
                   operation_state=resp_dict['operationState'],
                   state_entered_time=resp_dict['stateEnteredTime'],
                   start_time=resp_dict['startTime'],
                   vnf_instance_id=resp_dict['vnfInstanceId'],
                   operation_type=resp_dict['operation'],
                   is_automatic_invocation=resp_dict['isAutomaticInvocation'],
                   operation_params=resp_dict.get('operationParams', None),
                   is_cancel_pending=resp_dict['isCancelPending'],
                   links=links,
                   grant_id=resp_dict.get('grantId', None),
                   operation_name=resp_dict.get('operationName', None),
                   cancel_mode=resp_dict.get('cancelMode', None),
                   error=resp_dict.get('error', None),
                   resource_changes=resp_dict.get('resourceChanges', None),
                   changed_info=resp_dict.get('changedInfo', None),
                   additional_data=resp_dict.get('additionalData', None))

    def as_dict(self):
        result = {'id': self.operation_id,
                  'operationState': self.operation_state,
                  'stateEnteredTime': self.state_entered_time,
                  'startTime': self.start_time,
                  'vnfInstanceId': self.vnf_instance_id,
                  'operation': self.operation_type,
                  'isAutomaticInvocation': self.is_automatic_invocation,
                  'operationParams': self.operation_params,
                  'isCancelPending': self.is_cancel_pending}

        links = None
        if self.links is not None:
            links = self.links.as_dict()

        attributes = {'grantId': self.grant_id,
                      'operationName': self.operation_name,
                      'cancelMode': self.cancel_mode,
                      'error': self.error,
                      'resourceChanges': self.resource_changes,
                      'changedInfo': self.changed_info,
                      'additionalData': self.additional_data,
                      '_links': links}

        attributes = {k: v for k, v in attributes.items() if v}
        result.update(attributes)

        return result
